// Migrates packs-src/core runbooks to the v2 document model: ONE document
// per runbook AREA (packs-src/core/content/runbooks/<area>.md), in which
// each runbook is a `##` section carrying its own tags via a section-tags
// marker; the runbook's own headings are demoted by two levels (fenced
// code untouched). Core *reference* content is generated by
// scripts/gen_core_pack.mjs and is intentionally NOT touched here.
//
// Usage: node scripts/migrate_core_runbooks.mjs [--write] [--delete-old]
import { existsSync, readdirSync, readFileSync, writeFileSync, rmSync } from "node:fs";
import { join } from "node:path";

const ROOT = process.cwd();
const RB = join(ROOT, "packs-src", "core", "content", "runbooks");
const WRITE = process.argv.includes("--write");
const DELETE_OLD = process.argv.includes("--delete-old");

function parseFrontmatter(text) {
  const m = /^---\n([\s\S]*?)\n---\n?/.exec(text);
  if (!m) return { fm: {}, body: text };
  const fm = {};
  for (const line of m[1].split("\n")) {
    const kv = /^(\w+)\s*=\s*(.+)$/.exec(line.trim());
    if (!kv) continue;
    const v = kv[2].trim();
    fm[kv[1]] = v.startsWith("[")
      ? [...v.matchAll(/"([^"]*)"/g)].map((x) => x[1])
      : v.replace(/^"|"$/g, "");
  }
  return { fm, body: text.slice(m[0].length) };
}

function demote(body) {
  let fence = false;
  return body
    .split("\n")
    .map((line) => {
      if (line.startsWith("```")) fence = !fence;
      if (fence) return line;
      const h = /^(#{1,6})(\s+.*)$/.exec(line);
      return h ? "#".repeat(Math.min(6, Math.max(4, h[1].length + 2))) + h[2] : line;
    })
    .join("\n");
}

let failures = 0;
for (const area of readdirSync(RB, { withFileTypes: true }).filter((e) => e.isDirectory())) {
  const dir = join(RB, area.name);
  const files = readdirSync(dir)
    .filter((n) => n.endsWith(".md"))
    .sort()
    .map((n) => {
      const { fm, body } = parseFrontmatter(readFileSync(join(dir, n), "utf8"));
      return { name: n, path: join(dir, n), fm, body };
    });
  if (!files.length) continue;
  const tags = [];
  for (const f of files) for (const t of f.fm.tags ?? []) if (!tags.includes(t)) tags.push(t);
  if (!tags.includes("model-doc")) tags.push("model-doc");
  const title = area.name === "os-linux" ? "Runbooks: Linux" : `Runbooks: ${area.name[0].toUpperCase() + area.name.slice(1)}`;
  let out = `---\nid = "doc/runbooks/${area.name}"\nkind = "runbook"\ntitle = "${title}"\ncategory = "runbooks/${area.name}"\ntags = [${tags.map((t) => `"${t}"`).join(", ")}]\nrisk = "info"\nversion = "${files[0].fm.version ?? "core"}"\n---\nEvery ${area.name} runbook in one document (v2 document model — see\ndocs/PACK-SPEC.md). Each runbook is a section carrying its own tags.\n`;
  for (const f of files) {
    const shortTitle = (f.fm.title ?? f.name).replace(/^Runbook:\s*/, "");
    out += `\n\n## ${shortTitle}\n<!-- section-tags: ${(f.fm.tags ?? []).join(", ")} -->\n\n${demote(f.body.trim())}\n`;
    if (!out.includes(shortTitle)) failures++;
  }
  console.log(`${area.name}: ${files.length} runbooks → runbooks/${area.name}.md`);
  if (WRITE) writeFileSync(join(RB, `${area.name}.md`), out);
  if (WRITE && DELETE_OLD) for (const f of files) rmSync(f.path);
}
console.log(`failures: ${failures}`);
process.exit(failures ? 1 : 0);
